B.bF1=new A.it("\u0421\u043e\u0447\u0435\u0442\u0430\u043d\u0438\u044f \u0416\u0418-\u0428\u0418, \u0427\u0410-\u0429\u0410, \u0427\u0423-\u0429\u0423, \u0427\u041a-\u0427\u041d-\u0429\u041d \u2014 \u044d\u0442\u043e \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0440\u0444\u043e\u0433\u0440\u0430\u043c\u043c\u044b. \u0412 \u0434\u0440\u0435\u0432\u043d\u0435\u0440\u0443\u0441\u0441\u043a\u043e\u043c \u044f\u0437\u044b\u043a\u0435 \u0437\u0432\u0443\u043a\u0438 [\u0436] \u0438 [\u0448] \u0431\u044b\u043b\u0438 \u043c\u044f\u0433\u043a\u0438\u043c\u0438, \u0430 \u043f\u043e\u0437\u0436\u0435 \u043e\u0442\u0432\u0435\u0440\u0434\u0435\u043b\u0438, \u043d\u043e \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u0431\u0443\u043a\u0432\u044b \u0418 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u043e\u0441\u044c \u043f\u043e \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u0438. \u0417\u0432\u0443\u043a\u0438 [\u0447'] \u0438 [\u0449'] \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0432\u0441\u0435\u0433\u0434\u0430 \u043c\u044f\u0433\u043a\u0438\u043c\u0438 \u043d\u0435\u043f\u0430\u0440\u043d\u044b\u043c\u0438, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0438\u043c \u043d\u0435 \u043d\u0443\u0436\u0435\u043d \u043c\u044f\u0433\u043a\u0438\u0439 \u0437\u043d\u0430\u043a \u0434\u043b\u044f \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043c\u044f\u0433\u043a\u043e\u0441\u0442\u0438 (\u0432 \u0441\u043e\u0447\u0435\u0442\u0430\u043d\u0438\u044f\u0445 \u0427\u041a, \u0427\u041d, \u0429\u041d), \u0430 \u043f\u043e\u0441\u043b\u0435 \u043d\u0438\u0445 \u043f\u0438\u0448\u0443\u0442\u0441\u044f \u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0410, \u0423 (\u0427\u0410-\u0429\u0410, \u0427\u0423-\u0429\u0423).",B.bcW,"\u0414\u0435\u0442\u0438 \u043f\u0438\u0448\u0443\u0442 \u0436\u044b\u0440\u0430\u0444, \u043c\u0430\u0448\u044b\u043d\u0430, \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0441\u043b\u044b\u0448\u0430\u0442 \u0442\u0432\u0451\u0440\u0434\u044b\u0439 \u0437\u0432\u0443\u043a [\u0436] \u0438 [\u0448]. \u041b\u043e\u0432\u0443\u0448\u043a\u0430 \u0441\u043b\u0443\u0445\u0430: \u0441\u043b\u044b\u0448\u0438\u043c [\u044b], \u043d\u043e \u043f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0443 \u043f\u0438\u0448\u0435\u043c \u0431\u0443\u043a\u0432\u0443 \u0418!","\u0416\u0438 \u0438 \u0448\u0438 \u0441 \u0431\u0443\u043a\u0432\u043e\u0439 \u0418 \u043f\u0438\u0448\u0438! \u0427\u0430 \u0438 \u0449\u0430 \u0441 \u0431\u0443\u043a\u0432\u043e\u0439 \u0410 \u043f\u0438\u0448\u0438! \u0427\u0443 \u0438 \u0449\u0443 \u0441 \u0431\u0443\u043a\u0432\u043e\u0439 \u0423 \u043f\u0438\u0448\u0438! \u0427\u043a, \u0447\u043d, \u0449\u043d \u2014 \u0431\u0435\u0437 \u043c\u044f\u0433\u043a\u043e\u0433\u043e \u0437\u043d\u0430\u043a\u0430!",'\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0417\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0433\u043b\u0430\u0437\u0430 \u0438 \u043f\u043e\u0441\u043b\u0443\u0448\u0430\u0439\u0442\u0435 \u0441\u043b\u043e\u0432\u043e: [\u0436\u044b-\u044b-\u044b\u0437\u043d\u044c]. \u041a\u0430\u043a\u043e\u0439 \u0437\u0432\u0443\u043a \u043c\u044b \u0441\u043b\u044b\u0448\u0438\u043c \u043f\u043e\u0441\u043b\u0435 [\u0436]?"\n\u0414\u0435\u0442\u0438: "\u0421\u043b\u044b\u0448\u0438\u0442\u0441\u044f \u042b!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u041d\u043e \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0442\u0435\u0442\u0440\u0430\u0434\u044c: \u043f\u043e\u0447\u0435\u043c\u0443 \u0436\u0435 \u043c\u044b \u043f\u0438\u0448\u0435\u043c \u0431\u0443\u043a\u0432\u0443 \u0418?"\n\u0414\u0435\u0442\u0438: "\u041f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0416\u0418 \u0438 \u0428\u0418 \u0434\u0440\u0443\u0436\u0430\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0441 \u0431\u0443\u043a\u0432\u043e\u0439 \u0418! \u042d\u0442\u043e \u0437\u0430\u043a\u043e\u043d \u0440\u0443\u0441\u0441\u043a\u043e\u0433\u043e \u044f\u0437\u044b\u043a\u0430!"',B.ba2,B.bkg,'\u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043b \u043f\u0438\u0441\u044c\u043c\u043e \u0434\u0440\u0443\u0433\u0443: "\u041b\u0435\u0442\u043e\u043c \u044f \u043f\u043e\u0439\u043c\u0430\u043b \u043e\u0433\u0440\u043e\u043c\u043d\u0443\u044e \u0429\u042e\u041a\u0423 \u0438 \u043f\u0438\u043b \u0427\u042f\u0419 \u0441 \u0416\u042b\u0440\u043d\u044b\u043c \u043f\u0438\u0440\u043e\u0436\u043a\u043e\u043c!"',B.bAH,"1 - 2 - 3 - 4 - 5","\u0427\u0410\u0419\u041a\u0410","\u041a\u0430\u043a\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0441 \u0431\u0443\u043a\u0432\u043e\u0439 \u0418, \u0445\u043e\u0442\u044f \u043f\u043e\u0441\u043b\u0435 \u0442\u0432\u0435\u0440\u0434\u043e\u0433\u043e \u0448\u0438\u043f\u044f\u0449\u0435\u0433\u043e \u043c\u044b \u043e\u0442\u0447\u0435\u0442\u043b\u0438\u0432\u043e \u0441\u043b\u044b\u0448\u0438\u043c \u0437\u0432\u0443\u043a [\u044b]?",B.bcE,"\u043c\u0430\u0448\u0438\u043d\u0430 (\u0441\u043e\u0447\u0435\u0442\u0430\u043d\u0438\u0435 \u0428\u0418 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0441 \u0418)","\u0421\u0432\u044f\u0437\u043a\u0438 \u0431\u0443\u043a\u0432: \u0436\u0438, \u0448\u0438, \u0447\u0430, \u0449\u0430, \u0447\u0443, \u0449\u0443, \u0447\u043a, \u0447\u043d \u0441 \u043f\u043b\u0430\u0432\u043d\u044b\u043c \u043d\u0438\u0436\u043d\u0438\u043c \u0438 \u0441\u0440\u0435\u0434\u043d\u0438\u043c \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435\u043c.","1. \u041f\u0440\u043e\u043f\u0443\u0441\u043a\u0438: \u0436_\u0437\u043d\u044c (\u0438), \u0447_\u0448\u043a\u0430 (\u0430), \u0449_\u043a\u0430 (\u0443). 2. \u0422\u0430\u0431\u043b\u0438\u0446\u0430: \u0416\u0418-\u0428\u0418: \u0436\u0438\u0437\u043d\u044c, \u0448\u0438\u0448\u043a\u0430, \u043b\u044b\u0436\u0438; \u0427\u0410-\u0429\u0410: \u0447\u0430\u0449\u0430, \u0447\u0430\u0439\u043a\u0430; \u0427\u0423-\u0429\u0423: \u0449\u0443\u043a\u0430, \u0447\u0443\u0434\u043e, \u0447\u0443\u043b\u0430\u043d. 3. \u041e\u0448\u0438\u0431\u043a\u0430 \u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0438: \u0449\u0443\u043a\u0443, \u0447\u0430\u0439, \u0436\u0438\u0440\u043d\u044b\u043c. 7. \u0428\u0438\u0444\u0440: \u0427\u0410\u0419\u041a\u0410. 8. \u0422\u0420\u0418\u0417: \u043c\u0430\u0448\u0438\u043d\u0430.")
B.btY=s(["\u0411\u0435\u0437\u0443\u0434\u0430\u0440\u043d\u044b\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u2014 \u043a\u0430\u043a \u0441\u043f\u044f\u0449\u0438\u0439 \u0431\u043e\u0433\u0430\u0442\u044b\u0440\u044c: \u0433\u043e\u0432\u043e\u0440\u0438\u0442 \u0442\u0438\u0445\u043e, \u043d\u0435\u0432\u043d\u044f\u0442\u043d\u043e. \u0423\u0434\u0430\u0440\u0435\u043d\u0438\u0435 \u2014 \u0432\u043e\u043b\u0448\u0435\u0431\u043d\u044b\u0439 \u043a\u043e\u043b\u043e\u043a\u043e\u043b\u044c\u0447\u0438\u043a, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0431\u0443\u0434\u0438\u0442 \u0431\u043e\u0433\u0430\u0442\u044b\u0440\u044f, \u0438 \u0442\u043e\u0442 \u0437\u0432\u0443\u0447\u0438\u0442 \u0432\u043e \u0432\u0441\u044e \u0441\u0438\u043b\u0443.","\u041f\u0440\u043e\u0432\u0435\u0440\u043e\u0447\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u2014 \u0444\u043e\u043d\u0430\u0440\u0438\u043a \u0441\u044b\u0449\u0438\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u044f\u0440\u043a\u043e \u043e\u0441\u0432\u0435\u0449\u0430\u0435\u0442 \u0441\u043e\u043c\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0431\u0443\u043a\u0432\u0443."],t.s)
B.aGb=s(["\u0421\u043b\u043e\u0432\u043e \u0441 \u0441\u043e\u043c\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0433\u043b\u0430\u0441\u043d\u043e\u0439","\u041f\u0440\u043e\u0432\u0435\u0440\u043e\u0447\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e (\u043f\u043e\u0434 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u0435\u043c)"],t.s)
B.bvk=s(["\u0442\u0440_\u0432\u0430","\u0442\u0440\u0430\u0432\u044b","\u0441_\u0441\u043d\u0430","\u0441\u043e\u0441\u043d\u044b","\u0433\u0440_\u0431\u044b","\u0433\u0440\u0438\u0431","\u043f_\u043b\u044f","\u043f\u043e\u043b\u0435"],t.s)
B.byI=new A.aj(B.jI,["\u0412","\u041e","\u0414","\u0410"],t.w)
B.bl3=s(["\u0441\u0442_\u043b\u044b (\u0441\u0442\u043e\u043b)","\u0442\u0440_\u0432\u0430 (\u0442\u0440\u0430\u0432\u044b)","\u0441_\u0434\u044b (\u0441\u0430\u0434)","\u0441\u0442\u0440_\u043d\u0430 (\u0441\u0442\u0440\u0430\u043d\u044b)"],t.s)
B.bF2=new A.it("\u0412 \u0431\u0435\u0437\u0443\u0434\u0430\u0440\u043d\u043e\u043c \u0441\u043b\u043e\u0433\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0437\u0432\u0443\u043a\u0438 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0441\u043b\u0430\u0431\u0435\u0435, \u0441\u043c\u0430\u0437\u0430\u043d\u043d\u043e \u0438 \u0442\u0435\u0440\u044f\u044e\u0442 \u0447\u0435\u0442\u043a\u043e\u0441\u0442\u044c \u0437\u0432\u0443\u0447\u0430\u043d\u0438\u044f. \u0427\u0442\u043e\u0431\u044b \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e \u043d\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0431\u0435\u0437\u0443\u0434\u0430\u0440\u043d\u0443\u044e \u0433\u043b\u0430\u0441\u043d\u0443\u044e \u0432 \u043a\u043e\u0440\u043d\u0435 \u0441\u043b\u043e\u0432\u0430, \u043d\u0443\u0436\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0435\u0451 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u0435\u043c: \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u0444\u043e\u0440\u043c\u0443 \u0441\u043b\u043e\u0432\u0430 (\u0433\u043e\u0440\u0430 \u2014 \u0433\u043e\u0301\u0440\u044b, \u0432\u043e\u0434\u0430 \u2014 \u0432\u043e\u0301\u0434\u044b) \u0438\u043b\u0438 \u043f\u043e\u0434\u043e\u0431\u0440\u0430\u0442\u044c \u043e\u0434\u043d\u043e\u043a\u043e\u0440\u0435\u043d\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e (\u0442\u0440\u0430\u0432\u0430 \u2014 \u0442\u0440\u0430\u0301\u0432\u043a\u0430, \u043b\u0435\u0441\u043d\u043e\u0439 \u2014 \u043b\u0435\u0441), \u0433\u0434\u0435 \u044d\u0442\u043e\u0442 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0441\u0442\u0430\u043d\u0435\u0442 \u0443\u0434\u0430\u0440\u043d\u044b\u043c.",B.btY,"\u0414\u0435\u0442\u0438 \u043f\u0438\u0448\u0443\u0442 \u0431\u0435\u0437\u0443\u0434\u0430\u0440\u043d\u044b\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u043f\u043e \u0441\u043b\u0443\u0445\u0443 (*\u0441\u0430\u0441\u043d\u0430* \u0432\u043c\u0435\u0441\u0442\u043e *\u0441\u043e\u0441\u043d\u0430*). \u041b\u043e\u0432\u0443\u0448\u043a\u0430: \u0441\u043b\u0443\u0445 \u043e\u0431\u043c\u0430\u043d\u044b\u0432\u0430\u0435\u0442, \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u0435\u043c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430!","\u0415\u0441\u043b\u0438 \u0431\u0443\u043a\u0432\u0430 \u0433\u043b\u0430\u0441\u043d\u0430\u044f \u0432\u044b\u0437\u0432\u0430\u043b\u0430 \u0441\u043e\u043c\u043d\u0435\u043d\u0438\u0435 \u2014 \u0442\u044b \u043d\u0435\u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e \u0435\u0451 \u043f\u043e\u0441\u0442\u0430\u0432\u044c \u043f\u043e\u0434 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u0435!",'\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u041f\u0440\u043e\u0438\u0437\u043d\u0435\u0441\u0438\u0442\u0435 \u0441\u043b\u043e\u0432\u043e: [\u0442\u0440\u0430\u0432\xe1]. \u041a\u0430\u043a\u043e\u0439 \u0437\u0432\u0443\u043a \u043c\u044b \u0441\u043b\u044b\u0448\u0438\u043c \u0432 \u043f\u0435\u0440\u0432\u043e\u043c \u0441\u043b\u043e\u0433\u0435?"\n\u0414\u0435\u0442\u0438: "\u0417\u0432\u0443\u043a [\u0430]!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0410 \u0432 \u0441\u043b\u043e\u0432\u0435 [\u0433\u0430\u0440\xe1] \u043a\u0430\u043a\u043e\u0439 \u0437\u0432\u0443\u043a \u0441\u043b\u044b\u0448\u0438\u043c?"\n\u0414\u0435\u0442\u0438: "\u0422\u043e\u0436\u0435 [\u0430]!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0410 \u043a\u0430\u043a \u0436\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c, \u043a\u0430\u043a\u0443\u044e \u0431\u0443\u043a\u0432\u0443 \u043f\u0438\u0441\u0430\u0442\u044c \u2014 \u041e \u0438\u043b\u0438 \u0410? \u041f\u043e\u0434\u0441\u0442\u0430\u0432\u0438\u043c \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u0435!"\n\u041c\u0438\u0448\u0430: "\u0413\u043e\u0301\u0440\u044b! \u0427\u0435\u0442\u043a\u043e \u0441\u043b\u044b\u0448\u043d\u043e \u0431\u0443\u043a\u0432\u0443 \u041e! \u0417\u043d\u0430\u0447\u0438\u0442, \u0432 \u0441\u043b\u043e\u0432\u0435 \u0433\u043e\u0440\u0430 \u043f\u0438\u0448\u0435\u043c \u041e!"',B.aGb,B.bvk,'\u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043b \u0432 \u0442\u0435\u0442\u0440\u0430\u0434\u0438: "\u041d\u0430 \u0433\u043e\u0440\u0435 \u0440\u0430\u0441\u0442\u0443\u0442 \u043a\u0440\u0430\u0441\u0438\u0432\u044b\u0435 \u0421\u0410\u0411\u041e\u0420\u0418\u041a\u0418". \u041e\u043d \u0433\u043e\u0432\u043e\u0440\u0438\u0442: "\u042f \u0441\u043b\u044b\u0448\u0443 [\u0430], \u0437\u043d\u0430\u0447\u0438\u0442 \u0438 \u043f\u0438\u0448\u0443 \u0410!"',B.byI,"1 - 2 - 3 - 4","\u0412\u041e\u0414\u0410","\u041d\u0430\u0439\u0434\u0438 \u0441\u043b\u043e\u0432\u043e, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u0435\u043c \u0434\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u0431\u0443\u043a\u0432\u044b \u041e:",B.bl3,"\u0441\u0442\u043e\u043b\u044b (\u043f\u0440\u043e\u0432\u0435\u0440\u043e\u0447\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0421\u0422\u041e\u041b, \u043f\u0438\u0448\u0435\u043c \u0431\u0443\u043a\u0432\u0443 \u041e)","\u041f\u0440\u043e\u043f\u0438\u0441\u044b\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u0440 \u0441\u043b\u043e\u0432: \u0432\u043e\u043b\u043d\u0430 \u2014 \u0432\u043e\u043b\u043d\u044b, \u0442\u0440\u0430\u0432\u0430 \u2014 \u0442\u0440\u0430\u0432\u044b \u0441 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043f\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u043e\u0439 \u0437\u043d\u0430\u043a\u0430 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u044f.","1. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430: \u0442\u0440\u0430\u0432\u0430 \u2014 \u0442\u0440\u0430\u0432\u044b, \u0441\u043e\u0441\u043d\u0430 \u2014 \u0441\u043e\u0441\u043d\u044b, \u0433\u0440\u0438\u0431\u044b \u2014 \u0433\u0440\u0438\u0431, \u043f\u043e\u043b\u044f \u2014 \u043f\u043e\u043b\u0435. 2. \u0422\u0430\u0431\u043b\u0438\u0446\u0430: \u0421\u043e\u043c\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435: \u0442\u0440_\u0432\u0430, \u0441_\u0441\u043d\u0430, \u0433\u0440_\u0431\u044b, \u043f_\u043b\u044f; \u041f\u0440\u043e\u0432\u0435\u0440\u043e\u0447\u043d\u044b\u0435: \u0442\u0440\u0430\u0432\u044b, \u0441\u043e\u0441\u043d\u044b, \u0433\u0440\u0438\u0431, \u043f\u043e\u043b\u0435. 3. \u041e\u0448\u0438\u0431\u043a\u0430 \u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0438: \u0437\u0430\u0431\u043e\u0440, \u043f\u0438\u0448\u0435\u043c \u0431\u0443\u043a\u0432\u0443 \u041e. 7. \u0428\u0438\u0444\u0440: \u0412\u041e\u0414\u0410. 8. \u0422\u0420\u0418\u0417: \u0441\u0442\u043e\u043b\u044b.")
B.bdn=s(["\u0421\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u2014 \u0441\u0431\u043e\u0440 \u0434\u0440\u0443\u0437\u0435\u0439 \u0432 \u043e\u0434\u0438\u043d \u0432\u0435\u0441\u0435\u043b\u044b\u0439 \u0445\u043e\u0440\u043e\u0432\u043e\u0434.","\u0412\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 \u2014 \u043a\u043e\u0433\u0434\u0430 \u043f\u0442\u0438\u0447\u043a\u0438 \u0443\u043b\u0435\u0442\u0435\u043b\u0438 \u0441 \u0432\u0435\u0442\u043a\u0438 \u0438\u043b\u0438 \u0441\u044a\u0435\u043b\u0438 \u043a\u043e\u043d\u0444\u0435\u0442\u044b \u0438\u0437 \u043a\u043e\u0440\u043e\u0431\u043a\u0438.","\u0412\u0435\u0441\u044b \u0441 \u0434\u0432\u0443\u043c\u044f \u0447\u0430\u0448\u0430\u043c\u0438: \u0441\u0443\u043c\u043c\u0430 \u0440\u0430\u0432\u043d\u0430 \u0434\u0432\u0443\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u043c \u0433\u0438\u0440\u044c\u043a\u0430\u043c-\u0441\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u043c."],t.s)
B.bqb=s(["\u041f\u0440\u0438\u043c\u0435\u0440\u044b \u043d\u0430 \u0441\u043b\u043e\u0436\u0435\u043d\u0438\u0435 (+)","\u041f\u0440\u0438\u043c\u0435\u0440\u044b \u043d\u0430 \u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 (-)"],t.s)
B.b8R=s(["5 + 3 = 8","8 - 3 = 5","6 + 2 = 8","8 - 2 = 6","4 + 3 = 7","7 - 3 = 4","5 + 2 = 7","7 - 2 = 5"],t.s)
